describe('Locked Out User Login Error Message', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display error message when locked out user attempts to login', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.url().should('include', '/');
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="error"]').should('contain', 'Sorry, this user has been locked out');
  });

  it('should keep user on login page after failed locked out user login attempt', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.url().should('not.include', '/inventory');
    cy.get('[data-test="username"]').should('exist');
    cy.get('[data-test="password"]').should('exist');
  });

  it('should display error container with correct data-test attribute', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('[data-test="error"]').should('have.length', 1);
    cy.get('[data-test="error"]').invoke('text').then((text) => {
      expect(text).to.include('Sorry, this user has been locked out');
    });
  });

  it('should display error message with exact text match', () => {
    cy.get('[data-test="username"]').type('locked_out_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('[data-test="error"]').should('contain.text', 'Sorry, this user has been locked out');
  });
});
